"""Loopback HTTP assets and loopback-only Downloader copies generated by the Release downloader tests."""

import hashlib
import http.server
import stat
import threading
import sys
import zipfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "release"))
from release_package import build_downloaders


class ReleaseHandler(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def do_GET(self):
        self.server.requests += 1
        if getattr(self.server, "interrupt_archive", False) and self.path.endswith(self.server.archive_name):
            self.send_response(200)
            self.send_header("Content-Length", "9999")
            self.end_headers()
            self.wfile.write(b"partial")
            self.close_connection = True
            return
        super().do_GET()


def start_server(root, archive_name, add_cleanup):
    handler = lambda *args, **kwargs: ReleaseHandler(*args, directory=str(root), **kwargs)
    server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), handler)
    server.archive_name = archive_name
    server.requests = 0
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    add_cleanup(server.server_close)
    add_cleanup(thread.join)
    add_cleanup(server.shutdown)
    return server


def write_assets(assets, archive_name, members, file_mode):
    archive_path = assets / archive_name
    with zipfile.ZipFile(archive_path, "w") as archive:
        for name, content in members.items():
            info = zipfile.ZipInfo(name)
            info.create_system = 3
            info.external_attr = (stat.S_IFREG | file_mode) << 16
            archive.writestr(info, content)
    write_checksum(assets, archive_name)


def write_checksum(assets, archive_name):
    digest = hashlib.sha256((assets / archive_name).read_bytes()).hexdigest()
    (assets / "SHA256SUMS.txt").write_text(f"{digest}  {archive_name}\n", encoding="ascii")


def build_test_downloaders(repository, output):
    paths = build_downloaders(repository, output)
    for path in paths:
        data = path.read_bytes()
        if path.suffix == ".command":
            anchor = b"curl_protocol='=https'\n"
            injection = b"""if [[ "${AGENT_WORK_KIT_RELEASE_TEST_MODE:-}" == 1 && "${AGENT_WORK_KIT_RELEASE_TEST_BASE_URL:-}" == http://127.0.0.1:* ]]; then
    release_base="${AGENT_WORK_KIT_RELEASE_TEST_BASE_URL%/}/$release_tag"
    curl_protocol='=http,https'
fi
"""
        else:
            anchor = b'$base = "https://github.com/kurodog870153/agent-work-kit/releases/download/$releaseTag"\r\n'
            injection = rb"""if ($env:AGENT_WORK_KIT_RELEASE_TEST_MODE -eq '1' -and $env:AGENT_WORK_KIT_RELEASE_TEST_BASE_URL -match '^http://127\.0\.0\.1:[0-9]+$') {
    $base = $env:AGENT_WORK_KIT_RELEASE_TEST_BASE_URL.TrimEnd('/') + '/' + $releaseTag
}
""".replace(b"\n", b"\r\n")
        if data.count(anchor) != 1:
            raise ValueError(f"Downloader test injection anchor missing: {path}")
        path.write_bytes(data.replace(anchor, anchor + injection))
    return paths
